"""
Postmortem writer node.
Reads the full incident state after resolution and uses GPT-4o to generate
a structured blameless postmortem. Output is stored as postmortem_url in state.
"""
import logging
from datetime import datetime, timezone
from pydantic import BaseModel, Field
from langchain_openai import ChatOpenAI
from state.schema import IncidentState

logger = logging.getLogger(__name__)


class PostmortemOutput(BaseModel):
    """Structured postmortem document generated by GPT-4o after incident resolution."""
    title: str = Field(description="Short incident title, e.g. 'P1 Database Connection Pool Exhaustion'")
    summary: str = Field(description="2-3 sentence executive summary of what happened and impact")
    root_cause: str = Field(description="Clear technical explanation of the root cause")
    timeline_summary: str = Field(description="Narrative summary of key events during the incident")
    contributing_factors: list[str] = Field(description="List of 3-5 factors that contributed to the incident")
    action_items: list[str] = Field(description="List of 3-5 concrete follow-up action items to prevent recurrence")
    lessons_learned: str = Field(description="One paragraph on what the team learned")


llm = ChatOpenAI(model="gpt-4o", temperature=0)
structured_llm = llm.with_structured_output(PostmortemOutput)


def postmortem_writer(state: IncidentState) -> dict:
    """
    Generates a blameless postmortem using GPT-4o from the full incident state.
    Returns postmortem content stored as postmortem_url and updates timeline.
    """
    logger.info(f"[postmortem_writer] Writing postmortem for {state['incident_id']}")

    timeline_text = "\n".join([
        f"  {e['timestamp']} | {e['node']}: {e.get('summary', '')}"
        for e in state.get("timeline", [])
    ])

    prompt = f"""You are writing a blameless postmortem for a production incident.

Incident Details:
- ID: {state['incident_id']}
- Severity: {state['severity']}
- Type: {state['incident_type']}
- Affected Systems: {state['affected_systems']}
- Alert: {state['clean_alert']}
- Root Cause: {state['root_cause']}
- Confidence: {state['confidence']}
- Jira Ticket: {state.get('jira_ticket_id', 'N/A')}
- Investigation Rounds: {state['investigation_rounds']}

Timeline:
{timeline_text}

Write a thorough blameless postmortem. Focus on systems and processes, not people.
Action items should be specific and actionable."""

    result: PostmortemOutput = structured_llm.invoke(prompt)

    postmortem_content = f"""# {result.title}

## Summary
{result.summary}

## Root Cause
{result.root_cause}

## Timeline
{result.timeline_summary}

## Contributing Factors
{chr(10).join(f'- {f}' for f in result.contributing_factors)}

## Action Items
{chr(10).join(f'- {a}' for a in result.action_items)}

## Lessons Learned
{result.lessons_learned}
"""

    logger.info(f"[postmortem_writer] Postmortem generated: {result.title}")

    return {
        "postmortem_url": f"postmortem://{state['incident_id']}",
        "timeline": [{
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "node": "postmortem_writer",
            "summary": f"Postmortem written: {result.title}"
        }],
        "messages": [{"role": "assistant", "content": postmortem_content}]
    }